def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                urgent_opponents += 1
            if opp.get('budget', 0) > budget:
                rich_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev['bid']))
                except Exception:
                    pass

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    high_supply = supply >= 22
    low_supply = supply <= 17

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    desperation = 0
    if hp <= 2:
        desperation += 4
    elif hp <= 4:
        desperation += 3
    elif hp <= 6:
        desperation += 2
    if no_water_days >= 2:
        desperation += 4
    elif no_water_days >= 1:
        desperation += 2

    market_pressure = 0
    if low_supply:
        market_pressure += 3
    elif supply <= 20:
        market_pressure += 2
    else:
        market_pressure += 1
    market_pressure += min(2, urgent_opponents)
    if highest_prev >= 200:
        market_pressure += 2
    elif highest_prev >= 120:
        market_pressure += 1

    if desperation >= 6:
        target = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif desperation >= 4:
        target = max(DAILY_SALARY * 0.78, avg_prev * 0.9, highest_prev * 0.72)
    else:
        if high_supply and hp >= 7 and no_water_days == 0:
            target = DAILY_SALARY * 0.22
        elif market_pressure >= 5:
            target = max(DAILY_SALARY * 0.62, highest_prev * 0.55)
        elif market_pressure >= 3:
            target = max(DAILY_SALARY * 0.45, avg_prev * 0.45)
        else:
            target = DAILY_SALARY * 0.3

    if highest_prev > 400 and desperation < 4:
        target = min(target, DAILY_SALARY * 0.38)
    elif highest_prev > 220 and desperation < 6:
        target = min(target, DAILY_SALARY * 0.48)

    if rich_opponents >= 2 and low_supply and desperation >= 4:
        target += 8

    if day >= 8 and hp >= 6 and no_water_days == 0:
        target *= 0.9

    reserve = 0.0
    if hp > 4:
        reserve = DAILY_SALARY * 0.25
    if desperation >= 4:
        reserve = 0.0

    bid = min(budget - reserve, target)
    if bid < 0:
        bid = 0.0
    if desperation >= 6:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if supply < WATER_REQ + 5:
        return min(my_status['budget'], max(avg_prev * 1.1, DAILY_SALARY * 0.8))

    return min(my_status['budget'], max(avg_prev * 0.9, DAILY_SALARY * 0.4))
